package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.cli.Option;
import org.apache.commons.cli.OptionBuilder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class OptionBuilder_create_TriageGen2Test {

    private String description = "Test description";
    private String longopt = "longOpt";
    private boolean required = true;
    private boolean optionalArg = false;
    private int numberOfArgs = 1;
    private Object type = String.class;
    private char valuesep = ',';
    private String argName = "argName";

    @Before
    public void setUp() {
        OptionBuilder.withLongOpt(longopt)
                     .withDescription(description)
                     .isRequired(required)
                     .withValueSeparator(valuesep)
                     .withArgName(argName)
                     .hasArgs(numberOfArgs)
                     .withType(type);

        if (optionalArg) {
            OptionBuilder.hasOptionalArg();
        }
    }

    @Test
    public void testCreateValidOption() {
        Option option = OptionBuilder.create("opt");
        assertEquals("opt", option.getOpt());
        assertEquals(description, option.getDescription());
        assertEquals(longopt, option.getLongOpt());
        assertEquals(required, option.isRequired());
        assertEquals(optionalArg, option.hasArg());
        assertEquals(numberOfArgs, option.getArgs());
        assertEquals(type, option.getType());
        assertEquals(valuesep, option.getValueSeparator());
        assertEquals(argName, option.getArgName());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateNullOption() {
        OptionBuilder.create(null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateEmptyOption() {
        OptionBuilder.create("");
    }

    @Test
    public void testCreateWithReset() {
        Option option1 = OptionBuilder.create("opt1");
        Option option2 = OptionBuilder.create("opt2");

        assertEquals("opt1", option1.getOpt());
        assertEquals("opt2", option2.getOpt());
        assertEquals(description, option1.getDescription());
        assertEquals(description, option2.getDescription());
        assertEquals(longopt, option1.getLongOpt());
        assertEquals(longopt, option2.getLongOpt());
    }

    @Test
    public void testCreateWithDifferentConfigurations() {
        OptionBuilder.withLongOpt("newLongOpt")
                     .isRequired(false)
                     .withValueSeparator(';')
                     .withArgs(2)
                     .hasOptionalArgs(3)
                     .withType(Integer.class)
                     .withDescription("New description");

        Option option = OptionBuilder.create("opt");
        assertEquals("opt", option.getOpt());
        assertEquals("New description", option.getDescription());
        assertEquals("newLongOpt", option.getLongOpt());
        assertEquals(false, option.isRequired());
        assertEquals(true, option.hasOptionalArg());
        assertEquals(3, option.getArgs());
        assertEquals(Integer.class, option.getType());
        assertEquals(';', option.getValueSeparator());
    }

    @Test
    public void testCreateWithAllPropertiesSet() {
        OptionBuilder.withLongOpt("allPropertiesLongOpt")
                     .isRequired(true)
                     .hasOptionalArgs(1)
                     .withArgs(2)
                     .withValueSeparator('|')
                     .withType(Double.class)
                     .withDescription("All properties description")
                     .withArgName("allPropertiesArgName");

        Option option = OptionBuilder.create("opt");
        assertEquals("opt", option.getOpt());
        assertEquals("All properties description", option.getDescription());
        assertEquals("allPropertiesLongOpt", option.getLongOpt());
        assertEquals(true, option.isRequired());
        assertEquals(true, option.hasOptionalArg());
        assertEquals(2, option.getArgs());
        assertEquals(Double.class, option.getType());
        assertEquals('|', option.getValueSeparator());
        assertEquals("allPropertiesArgName", option.getArgName());
    }
}
